mapper.select:
SELECT
i.itinerary_id AS itineraryId,
i.title AS title,
i.country AS country,
i.city AS city,
i.thumbnail_img AS thumbnailImg,
i.visibility AS visibility,
/* 좋아요 개수 */ ( SELECT COUNT(*)
FROM TB_ITINERARY_LIKE x
WHERE x.itinerary_id = i.itinerary_id
) AS likeCount,
/* 북마크 개수 */ ( SELECT COUNT(*)
FROM TB_ITINERARY_BOOKMARK b
WHERE b.itinerary_id = i.itinerary_id
) AS bookmarkCount,
/* 댓글 개수 */ ( SELECT COUNT(*)
FROM TB_ITINERARY_COMMENT c
WHERE c.itinerary_id = i.itinerary_id
AND c.status = 'ACTIVE'
) AS commentCount
FROM TB_ITINERARY_LIKE l
INNER JOIN TB_ITINERARY i
ON i.itinerary_id = l.itinerary_id
WHERE l.user_id = #{value}
/* 삭제된 일정 제외 */ AND i.status = 'ACTIVE'
/* 내가 작성한 게시글 제외 */ AND i.user_id != #{value}
/* 다른 사람의 공개 일정만 */ AND i.visibility = 'PUBLIC'
ORDER BY l.created_at DESC

SELECT
i.itinerary_id AS itineraryId,
i.title,
i.country,
i.city,
i.thumbnail_img AS thumbnailImg,
i.visibility,
/* * 현재 일정의 전체 좋아요 수 */ ( SELECT COUNT(*)
FROM TB_ITINERARY_LIKE x
WHERE x.itinerary_id = i.itinerary_id
) AS likeCount,
/* * 현재 일정의 전체 북마크 수 */ ( SELECT COUNT(*)
FROM TB_ITINERARY_BOOKMARK b
WHERE b.itinerary_id = i.itinerary_id
) AS bookmarkCount,
/* * 삭제되지 않은 댓글 수 */ ( SELECT COUNT(*)
FROM TB_ITINERARY_COMMENT c
WHERE c.itinerary_id = i.itinerary_id
AND c.status = 'ACTIVE'
) AS commentCount
FROM TB_ITINERARY_LIKE l
INNER JOIN TB_ITINERARY i
ON i.itinerary_id = l.itinerary_id
WHERE l.user_id = #{value}
/* 삭제된 일정 제외 */ AND i.status = 'ACTIVE'
/* 공개 일정만 */ AND i.visibility = 'PUBLIC'
/* * 중요 * * 본인이 작성한 게시글은 * 좋아요한 게시글 목록에서 제외 */ AND i.user_id != #{value}
ORDER BY l.created_at DESC
